#!/usr/bin/env node
// Release signing for the Expo/React Native Android project generated by `expo prebuild`.
//
// Expo's template signs the `release` build type with the public debug keystore. That produces an
// installable APK for internal testing, but Google Play rejects it. When the owner provides an upload
// keystore through the four CI secrets below, this script switches the generated android/app/build.gradle
// to a `release` signing config that reads EVERYTHING from the environment at Gradle time — no password
// or alias is ever written into a file, and android/ itself is gitignored.
//
//   ANDROID_KEYSTORE_PATH       absolute path of the decoded .jks/.keystore (CI writes it to $RUNNER_TEMP)
//   ANDROID_KEYSTORE_PASSWORD   keystore password
//   ANDROID_KEY_ALIAS           key alias inside the keystore
//   ANDROID_KEY_PASSWORD        key password
//
// All four present  -> upload-keystore signing (Play-uploadable when it is the registered upload key)
// None present      -> template left untouched: debug-keystore signing, "internal testing only"
// Some present      -> hard error (a half-configured secret set must never produce a mislabelled build)
//
//   node scripts/configure-android-signing.cjs            # patch android/app/build.gradle in place
//   node scripts/configure-android-signing.cjs --print    # only report the mode, change nothing
const fs = require("node:fs");
const path = require("node:path");

const SECRET_VARS = ["ANDROID_KEYSTORE_PATH", "ANDROID_KEYSTORE_PASSWORD", "ANDROID_KEY_ALIAS", "ANDROID_KEY_PASSWORD"];

const RELEASE_SIGNING_CONFIG = `        release {
            // Added by scripts/configure-android-signing.cjs — values come from the environment at build time.
            storeFile file(System.getenv("ANDROID_KEYSTORE_PATH"))
            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias System.getenv("ANDROID_KEY_ALIAS")
            keyPassword System.getenv("ANDROID_KEY_PASSWORD")
        }
`;

function signingMode(env) {
  const present = SECRET_VARS.filter((name) => (env[name] || "").trim() !== "");
  if (present.length === 0) return { mode: "debug-keystore", present };
  if (present.length === SECRET_VARS.length) return { mode: "upload-keystore", present };
  const missing = SECRET_VARS.filter((name) => !present.includes(name));
  throw new Error(`Incomplete Android signing configuration: missing ${missing.join(", ")} (all four of ${SECRET_VARS.join(", ")} are required, or none).`);
}

// Pure text transformation so it can be unit-tested against the template Expo generates.
function applyUploadKeystore(gradle) {
  if (gradle.includes('System.getenv("ANDROID_KEYSTORE_PATH")')) return gradle; // idempotent
  const signingConfigsStart = gradle.indexOf("    signingConfigs {");
  if (signingConfigsStart < 0) throw new Error("android/app/build.gradle: signingConfigs block not found");
  const debugConfig = gradle.indexOf("        debug {", signingConfigsStart);
  if (debugConfig < 0) throw new Error("android/app/build.gradle: signingConfigs.debug block not found");
  const debugConfigEnd = gradle.indexOf("        }\n", debugConfig);
  if (debugConfigEnd < 0) throw new Error("android/app/build.gradle: signingConfigs.debug block is not closed as expected");
  const insertAt = debugConfigEnd + "        }\n".length;
  let out = gradle.slice(0, insertAt) + RELEASE_SIGNING_CONFIG + gradle.slice(insertAt);

  const buildTypes = out.indexOf("    buildTypes {");
  if (buildTypes < 0) throw new Error("android/app/build.gradle: buildTypes block not found");
  const release = out.indexOf("        release {", buildTypes);
  if (release < 0) throw new Error("android/app/build.gradle: buildTypes.release block not found");
  const releaseSigning = out.indexOf("signingConfig signingConfigs.debug", release);
  if (releaseSigning < 0) throw new Error("android/app/build.gradle: buildTypes.release does not use signingConfigs.debug (template changed?)");
  out = out.slice(0, releaseSigning) + "signingConfig signingConfigs.release" + out.slice(releaseSigning + "signingConfig signingConfigs.debug".length);
  return out;
}

function main() {
  const printOnly = process.argv.includes("--print");
  const { mode } = signingMode(process.env);
  const gradlePath = path.resolve(__dirname, "..", "android", "app", "build.gradle");
  if (mode === "upload-keystore") {
    const keystore = process.env.ANDROID_KEYSTORE_PATH;
    if (!fs.existsSync(keystore)) throw new Error(`ANDROID_KEYSTORE_PATH points to a missing file: ${keystore}`);
    if (!printOnly) {
      const before = fs.readFileSync(gradlePath, "utf8");
      const after = applyUploadKeystore(before);
      fs.writeFileSync(gradlePath, after);
    }
    console.log("android signing: upload keystore from CI secrets (release build type signed with signingConfigs.release)");
  } else {
    if (!printOnly && !fs.existsSync(gradlePath)) throw new Error(`missing ${gradlePath} — run \`npx expo prebuild --platform android\` first`);
    console.log("android signing: no keystore secrets — debug keystore (INTERNAL TESTING ONLY, Google Play will reject this build)");
    if (process.env.GITHUB_ACTIONS) {
      console.log("::warning title=Debug-signed Android build::No ANDROID_KEYSTORE_* secrets: the APK/AAB are signed with the public debug keystore. Installable for testing, not uploadable to Google Play.");
    }
  }
  if (process.env.GITHUB_OUTPUT) fs.appendFileSync(process.env.GITHUB_OUTPUT, `mode=${mode}\n`);
  return mode;
}

module.exports = { SECRET_VARS, signingMode, applyUploadKeystore };

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(`::error title=Android signing configuration failed::${error.message}`);
    process.exit(1);
  }
}
